Create a channel instance and call `channel.sendMessage()`:

```dart
final channel = DirectChannel('<target-user-id>');
await channel.sendMessage(
  SendMessageParams(
    messageParams: TextMessageParams(
      text: 'Hello!',
    ),
  ),
  callback: SendMessageCallback(
    onMessageSaved: (message) {
      print('Message saved locally');
    },
    onMessageSent: (code, message) {
      print('Message sent, code: $code');
    },
  ),
);
```

Messages in community channels are sent to a specific subchannel. Use `CommunitySubChannel` with the community ID and subchannel ID.

```ts
import { CommunitySubChannel, SendTextMessageParams } from '@nexconn/chat';

const channel = new CommunitySubChannel('<communityId>', '<subChannelId>');

const params = new SendTextMessageParams({ text: 'Hello, subchannel!' });
const { code, data } = await channel.sendMessage(params);
if (code === 0) {
  console.log('Message sent:', data);
} else {
  console.log('Send failed. Code:', code);
}
```

Construct a channel instance and call `reload()` to refresh its latest data from the local database.

<Tabs groupId="language">
<TabItem value="kotlin" label="Kotlin" default>

```kotlin
// Get a direct channel
val directChannel = DirectChannel("userId")

directChannel.reload { updatedChannel, error ->
    if (error == null && updatedChannel != null) {
        println("Channel ID: ${updatedChannel.channelId}")
        println("Unread count: ${updatedChannel.unreadCount}")
        println("Pinned: ${updatedChannel.isPinned}")
    } else {
        // Failed: ${error?.message}
    }
}

// Get a group channel
val groupChannel = GroupChannel("groupId")

groupChannel.reload { updatedChannel, error ->
    if (error == null && updatedChannel != null) {
        println("Channel ID: ${updatedChannel.channelId}")
    }
}
```

</TabItem>
<TabItem value="java" label="Java">

```java
// Get a direct channel
DirectChannel directChannel = new DirectChannel("userId");

directChannel.reload((updatedChannel, error) -> {
    if (error == null && updatedChannel != null) {
        System.out.println("Channel ID: " + updatedChannel.getChannelId());
        System.out.println("Unread count: " + updatedChannel.getUnreadCount());
        System.out.println("Pinned: " + updatedChannel.getIsPinned());
    } else {
        // Failed
    }
});

// Get a group channel
GroupChannel groupChannel = new GroupChannel("groupId");

groupChannel.reload((updatedChannel, error) -> {
    if (error == null && updatedChannel != null) {
        System.out.println("Channel ID: " + updatedChannel.getChannelId());
    }
});
```

</TabItem>
</Tabs>

Remove one or more channels from a tag. For example, remove the direct channel with "Tom" from all channels tagged "Training." After removal, the channel still exists but no longer carries the tag.

<Tabs groupId="language">
<TabItem value="kotlin" label="Kotlin" default>

```kotlin
Tag.getTags { tagList, error ->
    if (error == null && tagList != null) {
        val tag = tagList.firstOrNull { it.tagId == "peixunban" }

        if (tag != null) {
            tag.deleteChannels(
                listOf(
                    ChannelIdentifier(ChannelType.DIRECT, "userId1")
                )
            ) { error ->
                if (error == null) {
                    // Removed successfully
                } else {
                    // Failed: ${error.message}
                }
            }
        }
    }
}
```

</TabItem>
<TabItem value="java" label="Java">

```java
Tag.getTags((tagList, error) -> {
    if (error == null && tagList != null) {
        Tag tag = null;
        for (Tag t : tagList) {
            if ("peixunban".equals(t.getTagId())) {
                tag = t;
                break;
            }
        }

        if (tag != null) {
            List<ChannelIdentifier> channels = new ArrayList<>();
            channels.add(new ChannelIdentifier(ChannelType.DIRECT, "userId1"));

            tag.deleteChannels(channels, error2 -> {
                if (error2 == null) {
                    // Removed successfully
                } else {
                    // Failed
                }
            });
        }
    }
});
```

</TabItem>
